local M = class("PetardGiftBagModel", LikeOO.OODataBase)

function M:onCreate()
    M.super.onCreate(self)
    self:refreshData(self.m_params)
    self:getData()
end

function M:refreshData(m_params)
    self.m_activityData = m_params.activityData or {}
    self.m_openId = self.m_activityData.open_id
    self.m_version = m_params.m_version
    self.m_xlsxActivity = m_params.xlsxActivity
    self.m_mainActivityName = m_params.mainActivityName
    
    local serverData = m_params.serverData
    -- 礼包购买记录id
    self.m_giftDatas = self:trimGiftData(serverData.gift_log) 
    
    -- 已购买的皮肤礼包id
    self.m_skinDatas = self:trimSkinGiftData(serverData.clothes_done)
end

function M:trimSkinGiftData(clothes_done)
    local overGiftDatas = {}
    for i = 1, #clothes_done do
        local id = clothes_done[i]
        overGiftDatas[id] = id
    end
    local flower_clothesData = ConfigManager:getCfgByName("flower_clothes")
    local versionData = flower_clothesData[self.m_version]
    local tempDatas = nil
    for id, itemData in pairs(versionData) do
        -- 只卖一个皮肤
        local curBuyLog = overGiftDatas[id]
        local isBuy = (curBuyLog ~= nil)
        tempDatas= {
            id = id,
            xlsxData = itemData,
            -- 是否购买过
            isBuy = isBuy,
        }
        break
    end
    return tempDatas
end

function M:trimGiftData(serverGift_log)
    local overGiftDatas = {}
    for id, count in pairs(serverGift_log) do
        local curId = tonumber(id)
        overGiftDatas[curId] = count
    end
    local tempDatas = {}
    local season_data = UserDataManager.m_season_data or {}
    local curSeason = season_data.season or 0
    local flower_giftData = ConfigManager:getCfgByName("flower_gift")
    local versionData = flower_giftData[self.m_version]
    if versionData then
        for index, itemData in pairs(versionData) do
            if (curSeason >= itemData.season) then
                if (itemData.season1 < 0) or (itemData.season1 == curSeason) then
                    local giftId = index
                    local buyCount = overGiftDatas[giftId]
                    buyCount = (buyCount ~= nil) and buyCount or 0
                    local residueBuyCount = itemData.time_limit - buyCount
                    residueBuyCount = residueBuyCount > 0 and residueBuyCount or 0
                    table.insert(tempDatas,{
                        xlsxData = itemData,
                        index = index,
                        residueBuyCount = residueBuyCount,
                    })
                end
            end
        end
    end
    table.sort(tempDatas,function(itemData1, itemData2) 
        return itemData1.index < itemData2.index
    end)
    return tempDatas
end

--获取各个阶段结束时间
function M:getDayTimer()
    local curServerTimer = UserDataManager:getServerTime()
    local targetTimer = PushUtil:getTargetTimer(1)
    local timer = targetTimer - curServerTimer
    local day, hour, min, sec = GameUtil:getTimeLayoutBySecond(timer)
    if day > 0 then
        hour = hour + day * 24;
    end
    return string.format("%02d:%02d:%02d", hour, min, sec),timer
end

